namespace LunarCal.Core.Chat;

/// <summary>
/// FR-BYOK-7: Vendor-neutral response returned by <see cref="LunarCal.Core.Abstractions.IChatModelClient"/>.
/// </summary>
public sealed class ChatResponse
{
    /// <summary>
    /// Natural language text generated by the model, if any.
    /// </summary>
    public string? Text { get; init; }

    /// <summary>
    /// Tool calls requested by the model during this turn.
    /// </summary>
    public IReadOnlyList<ToolCall> ToolCalls { get; init; } = Array.Empty<ToolCall>();

    /// <summary>
    /// Reason why the model finished generating.
    /// </summary>
    public ChatFinishReason FinishReason { get; init; } = ChatFinishReason.Stop;

    /// <summary>
    /// Opaque state returned by the provider to preserve multi-turn context (e.g. Gemini thought signatures, spec §7).
    /// </summary>
    public string? ProviderState { get; init; }

    /// <summary>
    /// Token usage metrics for the turn (FR-DATA-3).
    /// </summary>
    public ChatTokenUsage? Usage { get; init; }

    /// <summary>
    /// The model identifier that processed the request.
    /// </summary>
    public string? ModelId { get; init; }

    /// <summary>
    /// Indicates whether the model requested any tool invocations.
    /// </summary>
    public bool HasToolCalls => ToolCalls.Count > 0;
}
